B.aMv=new A.iL("Kabul Edilebilir Kullan\u0131m",null)
B.aL7=new A.im("Uygulamay\u0131 yaln\u0131zca ki\u015fisel mekan analizi ama\xe7l\u0131 kullanabilirsiniz. A\u015fa\u011f\u0131daki davran\u0131\u015flar yasakt\u0131r:",null)
B.aIG=new A.eq("Uygulamay\u0131 k\xf6t\xfcye kullanmak veya ba\u015fkalar\u0131n\u0131n kullan\u0131m\u0131n\u0131 engellemek",null)
B.aIz=new A.eq("Otomatik botlar veya scraper kullanmak",null)
